{"kind": "content", "icon": "📖", "head": "पाठ में शामिल दो रचनाएँ", "points": ["वहाँ लिखी रचनाओं में से दो इस पाठ में दी गई हैं", "पहली: एक कविता — 'प्रतीक्षा करते हैं पत्थर'", "दूसरी: एक गद्य रचना — 'नदी के किनारे भी नदी है'", "दोनों में आविन्यों के पत्थर और रोन नदी का असर"], "say": "आविन्यों में लिखी गई रचनाओं में से, दो रचनाएँ, हमारे इस पाठ में दी गई हैं। पहली है एक कविता, जिसका शीर्षक है, प्रतीक्षा करते हैं पत्थर। और दूसरी है एक गद्य रचना, जिसका शीर्षक है, नदी के किनारे भी नदी है। दोनों रचनाओं में, आविन्यों के पुराने पत्थरों, और वहाँ बहती रोन नदी का, गहरा असर दिखता है। आइए, दोनों का भाव समझते हैं।"},
{"kind": "content", "icon": "🪨", "head": "कविता का भाव: प्रतीक्षा करते हैं पत्थर", "points": ["मठ के पत्थर सदियों से वहीं खड़े हैं", "उन्होंने साधुओं की प्रार्थना, मौन, आना-जाना सब देखा", "पत्थर चुप हैं, पर जैसे किसी का इंतज़ार कर रहे हों", "भाव: पत्थर निर्जीव नहीं — उनमें इतिहास और धीरज बसा है"], "say": "पहली रचना, कविता, प्रतीक्षा करते हैं पत्थर। इसका भाव समझिए। मठ के पत्थर, सैकड़ों सालों से, वहीं खड़े हैं। उन्होंने साधुओं की प्रार्थनाएँ सुनीं, उनका मौन देखा, लोगों का आना और जाना देखा। धूप, बारिश, सर्दी, सब कुछ सहा। पत्थर चुप हैं, बोलते नहीं, पर कवि को लगता है, जैसे वे धीरज के साथ, किसी की प्रतीक्षा कर रहे हों। कवि कहना चाहते हैं, कि पत्थर निर्जीव नहीं हैं। उनमें इतिहास बसा है, यादें बसी हैं, और सबसे बड़ा गुण बसा है, धीरज।"},
{"kind": "content", "icon": "🌊", "head": "गद्य का भाव: नदी के किनारे भी नदी है", "points": ["लेखक रोन नदी के किनारे बैठकर उसे बहते देखते", "नदी लगातार बहती है, कभी नहीं रुकती, कभी ख़ाली नहीं होती", "जो किनारे बैठकर उसे ध्यान से देखता है, वह भी नदी जैसा हो जाता है", "यानी देखने वाला भी उस बहाव का हिस्सा बन जाता है"], "say": "दूसरी रचना, गद्य, नदी के किनारे भी नदी है। लेखक, रोन नदी के किनारे बैठकर, उसे बहते हुए देखते थे। नदी लगातार बहती है, कभी रुकती नहीं, और कितना भी पानी बह जाए, कभी ख़ाली नहीं होती। लेखक को एक सुंदर अनुभव होता है। जो आदमी, नदी के किनारे बैठकर, उसे पूरे ध्यान से देखता है, वह भी धीरे-धीरे, नदी जैसा हो जाता है। उसका मन भी बहने लगता है। यानी किनारे पर बैठा देखने वाला भी, उस बहाव का हिस्सा बन जाता है। इसीलिए शीर्षक है, नदी के किनारे भी नदी है।"},
{"kind": "compare", "icon": "⚖️", "head": "नदी और कविता — एक जैसी", "left": {"icon": "🌊", "t": "नदी", "d": "सदियों से बह रही<br>कई धाराएँ आकर मिलती हैं<br>कभी ख़ाली नहीं होती<br>किनारे बैठने वाले को भी भिगो देती"}, "right": {"icon": "📜", "t": "कविता", "d": "सदियों से लिखी जा रही<br>कई कवियों के शब्द मिलते हैं<br>कभी ख़त्म नहीं होती<br>पढ़ने-सुनने वाले को भी भिगो देती"}, "say": "लेखक, नदी और कविता की, बहुत सुंदर तुलना करते हैं। नदी, सदियों से बह रही है। कविता भी, सदियों से लिखी जा रही है। नदी में, कई छोटी धाराएँ आकर मिलती हैं। कविता में भी, हर युग के कवियों के शब्द और भाव, आकर मिलते जाते हैं। नदी कभी ख़ाली नहीं होती, कविता भी कभी ख़त्म नहीं होती। और जैसे नदी, किनारे बैठने वाले को भी भिगो देती है, वैसे ही कविता, उसे पढ़ने और सुनने वाले को भी, अपने रस में भिगो देती है। जो कविता के पास बैठता है, वह भी थोड़ा-सा कवि हो जाता है।"},
{"kind": "content", "icon": "💡", "head": "पाठ का मूल संदेश", "points": ["सृजन (कुछ नया रचना) के लिए एकांत और शांति ज़रूरी", "पुरानी धरोहर को सँभालो, नए काम में लगाओ", "प्रकृति — नदी, पत्थर — से भी सीखो: धीरज और लगातार बहना", "कला और साहित्य देशों की सीमा नहीं मानते"], "say": "इस पाठ का मूल संदेश क्या है? पहला, सृजन, यानी कुछ नया रचने के लिए, एकांत और शांति ज़रूरी है। दूसरा, अपनी पुरानी धरोहर को तोड़ो मत, उसे सँभालो, और नए अच्छे काम में लगाओ, जैसे फ़्रांस ने पुराने मठ को, कला-केंद्र बना दिया। तीसरा, प्रकृति से सीखो। पत्थर से धीरज, और नदी से लगातार बहते रहना। और चौथा, कला और साहित्य, देशों की सीमा नहीं मानते। एक हिंदी कवि, फ़्रांस में बैठकर, हिंदी में कविता लिख रहा है।"},
{"kind": "table", "icon": "📋", "head": "पाठ के तथ्य — एक नज़र में", "eq": "याद रखने योग्य", "rows": [["बात", "तथ्य"], ["आविन्यों", "दक्षिण फ़्रांस, रोन नदी के किनारे"], ["मठ का नाम", "ला शत्रूज़ (कार्थूसियन संप्रदाय)"], ["लेखक का प्रवास", "19 दिन (24 जुलाई–10 अगस्त 1994)"], ["रचनाएँ", "35 कविताएँ, 27 गद्य रचनाएँ"], ["पाठ की कविता", "प्रतीक्षा करते हैं पत्थर"], ["पाठ का गद्य", "नदी के किनारे भी नदी है"]], "say": "पाठ के तथ्य, एक नज़र में। आविन्यों, दक्षिण फ़्रांस में, रोन नदी के किनारे है। मठ का नाम, ला शत्रूज़, जो कार्थूसियन संप्रदाय का था। लेखक वहाँ उन्नीस दिन रहे। वहाँ उन्होंने, पैंतीस कविताएँ, और सत्ताईस गद्य रचनाएँ लिखीं। पाठ में दी गई कविता है, प्रतीक्षा करते हैं पत्थर। और गद्य रचना है, नदी के किनारे भी नदी है।"},
{"kind": "table", "icon": "📋", "head": "कठिन शब्द", "eq": "शब्द और अर्थ", "rows": [["शब्द", "अर्थ"], ["मठ", "साधुओं के रहने और साधना की जगह"], ["एकांत", "अकेलापन, शांत जगह"], ["सृजन", "कुछ नया रचना"], ["प्रतीक्षा", "इंतज़ार"], ["रंग-समारोह", "नाटकों का उत्सव"], ["प्रवास", "कुछ समय के लिए कहीं रहना"], ["धरोहर", "विरासत, पुरखों की दी हुई चीज़"]], "say": "कुछ कठिन शब्द। मठ, साधुओं के रहने और साधना की जगह। एकांत, अकेलापन, शांत जगह। सृजन, कुछ नया रचना। प्रतीक्षा, इंतज़ार। रंग-समारोह, नाटकों का उत्सव। प्रवास, कुछ समय के लिए कहीं रहना। और धरोहर, यानी विरासत।"},
{"kind": "content", "icon": "🌾", "head": "बिहार से जुड़ाव", "points": ["बिहार में भी एकांत साधना की पुरानी जगहें: राजगीर की गुफाएँ, बराबर की गुफाएँ (जहानाबाद)", "नालंदा के खंडहर: पत्थर और ईंटें आज भी 'प्रतीक्षा' करती हैं", "गंगा, गंडक, कोसी, सोन: हमारी नदियाँ, हमारे गीत", "विद्यापति, दिनकर ने नदियों पर सुंदर कविताएँ लिखीं"], "say": "बिहार से जुड़ाव। हमारे बिहार में भी, एकांत साधना की, बहुत पुरानी जगहें हैं। राजगीर की गुफाएँ, और जहानाबाद की बराबर गुफाएँ, जहाँ हज़ारों साल पहले, साधु तपस्या करते थे। नालंदा के खंडहरों की ईंटें और पत्थर, आज भी जैसे, पुराने विद्यार्थियों की प्रतीक्षा कर रहे हैं। और हमारी नदियाँ, गंगा, गंडक, कोसी, सोन, हमारे लोकगीतों में बहती हैं। अगली बार, जब आप किसी नदी के किनारे बैठें, तो उसे ध्यान से देखिएगा, शायद आपके भीतर भी, कोई कविता बहने लगे।"},
{"kind": "list", "icon": "📝", "head": "सार", "points": ["लेखक: अशोक वाजपेयी · आविन्यों: दक्षिण फ़्रांस का शहर, रोन नदी पर", "ला शत्रूज़: पुराना ईसाई मठ, अब कला-केंद्र", "लेखक 19 दिन रहे · 35 कविताएँ, 27 गद्य रचनाएँ", "कविता: पत्थरों में धीरज और इतिहास", "गद्य: नदी और कविता एक जैसी — देखने वाला भी नदी हो जाता है"], "say": "आज का सार। एक, लेखक अशोक वाजपेयी हैं, और आविन्यों, दक्षिण फ़्रांस का, रोन नदी पर बसा शहर है। दो, ला शत्रूज़, एक पुराना ईसाई मठ है, जो अब कला-केंद्र है। तीन, लेखक वहाँ उन्नीस दिन रहे, और पैंतीस कविताएँ, और सत्ताईस गद्य रचनाएँ लिखीं। चार, कविता में, पत्थरों के धीरज और इतिहास का भाव है। पाँच, गद्य में, नदी और कविता की समानता है, कि देखने वाला भी, नदी हो जाता है।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 1", "q": "आविन्यों कहाँ है? वह किस नदी के किनारे बसा है?", "a": "दक्षिण फ़्रांस में · रोन नदी के किनारे", "pause": 4, "say": "अब अभ्यास। वीडियो रोककर उत्तर सोचिए। पहला, आविन्यों कहाँ है, और किस नदी के किनारे बसा है? ... दक्षिण फ़्रांस में, रोन नदी के किनारे।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 2", "q": "ला शत्रूज़ क्या है?", "a": "एक पुराना ईसाई मठ (कार्थूसियन संप्रदाय), अब कला-केंद्र", "pause": 5, "say": "दूसरा, ला शत्रूज़ क्या है? ... कार्थूसियन संप्रदाय का, एक पुराना ईसाई मठ, जो अब कलाकारों और लेखकों का केंद्र है।"},
